#!/usr/bin/env python3
"""Apply the locally verified acquisition diff, refusing any changed baseline.

The compressed payload is a UTF-8 unified diff of the listed source files.
No credentials, network operations, workflow changes, or delivery replay.
"""
import base64,hashlib,json,subprocess,zlib
from pathlib import Path
EXPECTED = {'scripts/acquisition_followup_smoke.py': {'old': None, 'new': 'b046841e7561b4d637ba72becc8a5c765a7d4fe4'}, 'scripts/card_acquisition.py': {'old': 'c2b0e23d582eeb25cfc8c41fd86a75e81490a59c', 'new': 'b54446b9806e8fa03c500934cdda7aa0e594deba'}, 'scripts/search_runtime.py': {'old': '8c0736e093681d01154cd8bc2310e538e3012ac2', 'new': '0dad55fc386043d5c373ea6fc59cc77beed8adad'}, 'scripts/social_depth.py': {'old': 'ae5dec2d83d4e0d7fd648462d151562ba3783087', 'new': 'fcfb83ee22322845274960436e45a211d969551f'}, 'scripts/social_leads_monitor.py': {'old': 'db31c8d4a425ae0b27bc26e5bf7c0e726dc09d46', 'new': '996003e74f54b08b26a3d3769d6592c4d846f5d7'}, 'scripts/tender_acquisition.py': {'old': '68c97f2800eca951e1efbe252f78956ed9775bc3', 'new': '35a219636d3b6c4c3960385a31b569dd3e79cfb8'}, 'scripts/tender_intake.py': {'old': None, 'new': '207f7e770c605a3be3e48416e01a6fc74fbcf29c'}, 'scripts/tender_monitor.py': {'old': 'bae60fa4b51f5784df77c005f6c99da3eec5c1c6', 'new': 'ff4476eb0357b6a35273b7a87666a69a96cf2b59'}, 'scripts/test_search_acquisition_followup.py': {'old': None, 'new': '8468c5663dd156b18d0ed65a38d0bf6cdcf51f4c'}}
PATCH = ""

def digest(raw):
    return hashlib.sha1(b'blob '+str(len(raw)).encode()+b'\0'+raw).hexdigest()

def main():
    actual={p:digest(Path(p).read_bytes()) if Path(p).exists() else None for p in EXPECTED}
    if all(actual[p]==v['new'] for p,v in EXPECTED.items()):
        print('Already applied');return
    bad=[p for p,v in EXPECTED.items() if actual[p]!=v['old']]
    if bad:raise RuntimeError('Refusing changed baseline: '+', '.join(bad))
    patch=zlib.decompress(base64.b64decode(PATCH))
    subprocess.run(['git','apply','--check','--whitespace=error-all','-'],input=patch,check=True)
    subprocess.run(['git','apply','--whitespace=error-all','-'],input=patch,check=True)
    for p,v in EXPECTED.items():
        if digest(Path(p).read_bytes())!=v['new']:raise RuntimeError('Post-apply digest mismatch: '+p)
    print('Applied reviewed files:',', '.join(EXPECTED))

if __name__=='__main__':main()
